assert("00100000");
assert("00100001");
assert("00010000");
assert("00010001");
assert("00001000");
assert("00001001");
assert("00000100");
assert(null, "default");
assert("", "default");
assert("other", "default");
System.Console.Write("RAN");

void assert(string input, string expected = null)
{
    if (C.M(input) != (expected ?? input))
    {
        throw new System.Exception($"{input} produced {C.M(input)}");
    }
}

public class C
{
    public static string M(string value)
    {
        return value switch
        {
            "00100000" => "00100000",
            "00100001" => "00100001",
            "00010000" => "00010000",
            "00010001" => "00010001",
            "00001000" => "00001000",
            "00001001" => "00001001",
            "00000100" => "00000100",
            "00000101" => "00000101",
            _ => "default"
        };
    }
}
